        let t8 = t5 * T::from_i64(2);
        let t9 = xv[0].mul_add(t3, t8);
        let t11 = (-t6).mul_add(T::from_i64(2), t7);
        let t12 = t0 + t1;
        let t13 = xv[2] * t12;
            return Point { o: core::marker::PhantomData, c: gx::slots::from_values::<S, T, 3>([t9, t11, t13]) };
